import cyclopts

app = cyclopts.App(name="myservice")


@app.command
def start():
    """Start the service."""
    print("Service started.")


@app.command
def stop():
    """Stop the service."""
    print("Service stopped.")


@app.default
def status():
    """Show service status (runs when no subcommand is given)."""
    print("Service status: running.")


if __name__ == "__main__":
    app()
